from typing import List, Tuple

def f(inputs: List[Tuple[int, int, str, str, str]]) -> List[int]:
    results = []
    for length, edit_distance, string1, string2, string3 in inputs:
        if length == 0 and edit_distance == 0:
            break
        changed_chars = sum(c1!= c2 for c1, c2 in zip(string1, string2))
        if changed_chars <= edit_distance:
            results.append(length)
        elif changed_chars <= edit_distance * 2:
            changed_chars = sum(c1!= c2 for c1, c2 in zip(string1, string3))
            if changed_chars <= edit_distance:
                results.append(length)
        else:
            results.append(length)
    return results
```

